// Generated by AI (UnitTest MCP)
//! Structural guard: every Bridge static page must present the identical
//! shared navigation, so a user on any one page can always reach every
//! other. Pages are discovered from the `static/` directory at test run
//! time (not a hand-maintained list), so a new page can never silently slip
//! through unchecked -- that gap is exactly what let `administration.html`
//! and `supervisors.html` land with their own, already-diverging nav after
//! the previous, hand-maintained version of this guard shipped.

use std::fs;
use std::path::Path;

const EVIDENCE: &str = include_str!("../static/evidence.html");

/// `index.html` is served at `/` and is the Fleet page; every other page's
/// filename already matches its own nav capability name (`evidence.html` ->
/// "Evidence"). This is the one exception, not a second list to forget.
fn capability_name(file_name: &str) -> String {
    let stem = file_name.trim_end_matches(".html");
    if stem == "index" {
        return "Fleet".to_string();
    }
    let mut chars = stem.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

/// Every `.html` file under `static/`, sorted for a deterministic order,
/// paired with its content and derived capability name.
fn discover_pages() -> Vec<(String, String, String)> {
    let static_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("static");
    let mut pages: Vec<(String, String, String)> = fs::read_dir(&static_dir)
        .unwrap_or_else(|error| panic!("reading {}: {error}", static_dir.display()))
        .filter_map(|entry| entry.ok())
        .filter(|entry| {
            entry
                .path()
                .extension()
                .is_some_and(|extension| extension == "html")
        })
        .map(|entry| {
            let file_name = entry.file_name().to_string_lossy().into_owned();
            let content = fs::read_to_string(entry.path())
                .unwrap_or_else(|error| panic!("reading {file_name}: {error}"));
            let capability = capability_name(&file_name);
            (file_name, content, capability)
        })
        .collect();
    pages.sort_by(|a, b| a.0.cmp(&b.0));
    assert!(
        !pages.is_empty(),
        "no .html pages found under {}",
        static_dir.display()
    );
    pages
}

/// The full capability set from ADR-0105 decision 5's Bridge navigation
/// surface (task:60ba293846ec). Agents and Readiness live as sections
/// inside the Fleet page itself, so they are not separate nav entries. Names
/// not yet backed by a real page in `static/` stay disabled placeholders
/// until their own page lands -- this list only needs a hand-edit for a
/// capability that has no page yet; once a page exists, `discover_pages`
/// and the tests below take over automatically.
const CAPABILITIES: &[&str] = &[
    "Fleet",
    "Evidence",
    "Telemetry",
    "Context",
    "Work",
    "Design",
    "Constitution",
    "Knowledge",
    "Administration",
    "Supervisors",
    "Delegations",
];

/// Extract the `<nav ...>...</nav>` block, with `aria-current="page"`
/// stripped and cosmetic whitespace removed. Whitespace BETWEEN tags has no
/// visual meaning here (the CSS flex `gap` controls spacing, not markup
/// whitespace) and is dropped entirely, since pages differ purely
/// cosmetically in whether their nav is packed onto one line or
/// pretty-printed across several. Whitespace INSIDE a tag (between
/// attributes) is real markup and is collapsed to one space, never dropped.
fn normalized_nav(page_name: &str, html: &str) -> String {
    let start = html
        .find("<nav")
        .unwrap_or_else(|| panic!("{page_name} is missing a <nav> element"));
    let end = html[start..]
        .find("</nav>")
        .map(|offset| start + offset + "</nav>".len())
        .unwrap_or_else(|| panic!("{page_name}'s <nav> element is never closed"));
    let nav = html[start..end].replace(" aria-current=\"page\"", "");

    let mut normalized = String::with_capacity(nav.len());
    let mut inside_tag = false;
    let mut chars = nav.chars().peekable();
    while let Some(character) = chars.next() {
        match character {
            '<' => {
                inside_tag = true;
                normalized.push(character);
            }
            '>' => {
                inside_tag = false;
                normalized.push(character);
            }
            whitespace if whitespace.is_whitespace() => {
                if inside_tag {
                    normalized.push(' ');
                    while chars.peek().is_some_and(|next| next.is_whitespace()) {
                        chars.next();
                    }
                }
            }
            other => normalized.push(other),
        }
    }
    normalized
}

#[test]
fn every_bridge_page_presents_the_same_navigation() {
    let pages = discover_pages();
    let (first_name, first_html, _) = &pages[0];
    let expected = normalized_nav(first_name, first_html);
    for (name, html, _) in &pages[1..] {
        let actual = normalized_nav(name, html);
        assert_eq!(
            actual, expected,
            "{name}'s navigation differs from {first_name}'s -- every Bridge page must share \
             the identical nav so pages stay reachable from each other"
        );
    }
}

#[test]
fn every_bridge_page_links_to_every_known_capability() {
    let pages = discover_pages();
    for (name, html, _) in &pages {
        let nav = normalized_nav(name, html);
        for capability in CAPABILITIES {
            assert!(
                nav.contains(&format!(">{capability}<")),
                "{name}'s navigation is missing the {capability} capability"
            );
        }
    }
}

#[test]
fn every_page_that_exists_is_a_real_link_not_a_disabled_placeholder() {
    // A page that ships must be reachable from the shared nav. Checking
    // only the first page is enough: the test above already proves every
    // page's nav is identical, so what is true here is true everywhere.
    let pages = discover_pages();
    let (first_name, first_html, _) = &pages[0];
    let nav = normalized_nav(first_name, first_html);
    for (file_name, _, capability) in &pages {
        assert!(
            nav.contains(&format!(">{capability}<")),
            "{file_name} exists under static/ but no page's nav links to it as \"{capability}\" \
             -- add it to CAPABILITIES and give every page a real link"
        );
        assert!(
            !nav.contains(&format!("aria-disabled=\"true\">{capability}<")),
            "{file_name} exists under static/ but its \"{capability}\" nav entry is still \
             aria-disabled -- a shipped page can never stay a disabled placeholder"
        );
    }
}

#[test]
fn every_disabled_capability_carries_no_href() {
    // A disabled nav entry with no href is not keyboard-focusable and is not
    // announced as a link by assistive tech -- the aria-disabled attribute
    // alone is not enough if a stray href turns it into a dead, focusable link.
    let pages = discover_pages();
    for (name, html, _) in &pages {
        let nav = normalized_nav(name, html);
        for segment in nav.split("<a ").skip(1) {
            if segment.contains("aria-disabled=\"true\"") {
                assert!(
                    !segment.contains("href="),
                    "{name}'s disabled nav entry ({segment}) must not carry an href"
                );
            }
        }
    }
}

#[test]
fn evidence_related_record_links_remain_separate_from_navigation() {
    // Evidence's own "#api-links" related-records section (a per-repository
    // raw-API deep link, labelled "Related Industrial records") is a
    // different feature from the shared page nav above and must stay that
    // way -- it must never be reintroduced by reusing the nav's own ids.
    for id in ["work-api", "constitution-api", "knowledge-api"] {
        assert!(
            EVIDENCE.contains(&format!("id=\"{id}\"")),
            "Evidence must retain its related-record link {id}"
        );
    }
    for removed_navigation_id in ["work-link", "constitution-link", "knowledge-link"] {
        assert!(
            !EVIDENCE.contains(&format!("id=\"{removed_navigation_id}\"")),
            "Evidence navigation must not rewire a capability placeholder through raw API links"
        );
    }
}
